// ==========================================
// 0. 特定人士授權白名單與 AES-256 加密金庫
// ==========================================
const ALLOWED_EMAILS = [
  "skunkqq@gmail.com",
  "sasadako.wu@gmail.com"
];

// AES-256-CBC 軍規加密金庫 Payload (PBKDF2 100,000 次疊代)
const ENCRYPTED_VAULT = {
  "salt": "OQUgxkzfV4KB+6nNLm6gTQ==",
  "iv": "J9nD0ctlSbBlodqqtl6FOw==",
  "ciphertext": ""
};

// 執行階段動態解密記憶體資料庫
let itineraryData = [];
