// ==========================================
// 0.1 高相容性 Base64 轉 Uint8Array 工具
// ==========================================
function base64ToUint8(base64Str) {
  const binaryString = atob(base64Str);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// ==========================================
// 0.2 Web Crypto API 客戶端零知識解密引擎
// ==========================================
async function decryptVault(password) {
  try {
    if (!window.crypto || !window.crypto.subtle) {
      throw new Error("此瀏覽器環境未支援 Web Crypto API，請使用現代瀏覽器開啟。");
    }

    const salt = base64ToUint8(ENCRYPTED_VAULT.salt);
    const iv = base64ToUint8(ENCRYPTED_VAULT.iv);
    const ciphertext = base64ToUint8(ENCRYPTED_VAULT.ciphertext);

    const encoder = new TextEncoder();
    const keyMaterial = await crypto.subtle.importKey(
      "raw",
      encoder.encode(password),
      { name: "PBKDF2" },
      false,
      ["deriveKey"]
    );

    const derivedKey = await crypto.subtle.deriveKey(
      {
        name: "PBKDF2",
        salt: salt,
        iterations: 100000,
        hash: "SHA-256"
      },
      keyMaterial,
      { name: "AES-CBC", length: 256 },
      false,
      ["decrypt"]
    );

    const decryptedBuffer = await crypto.subtle.decrypt(
      { name: "AES-CBC", iv: iv },
      derivedKey,
      ciphertext
    );

    const decoder = new TextDecoder("utf-8");
    const jsonStr = decoder.decode(decryptedBuffer);
    const data = JSON.parse(jsonStr);

    return { success: true, data };
  } catch (err) {
    console.warn("AES Decryption mismatch or error:", err);
    return { success: false, error: err };
  }
}

// ==========================================
// 1. 智慧時間狀態管理與變數
// ==========================================
// 依當前日期時間智慧定向：
// - 9/15 之前 -> 9/15
// - 9/15 當天 -> 9/15
// - 9/15 22:00 之後 -> 9/16
// - 9/16 當天 -> 9/16
// - 10/7 22:00 之後 或 10/7 以後 -> 9/15
function calculateDefaultFocusDate() {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth() + 1;
  const day = now.getDate();
  const hours = now.getHours();

  // 1. 2026 年 9/15 之前：轉到 9/15
  if (year < 2026 || (year === 2026 && (month < 9 || (month === 9 && day < 15)))) {
    return '9/15';
  }

  // 2. 2026 年 10/7 22:00 之後 或 10/7 以後：旅程結束轉回 9/15
  if (year > 2026 || (year === 2026 && (month > 10 || (month === 10 && (day > 7 || (day === 7 && hours >= 22)))))) {
    return '9/15';
  }

  // 3. 2026/09/15 ~ 2026/10/07 旅行期間：
  // 晚上 22:00 之後 -> 自動轉向隔天行程；未滿 22:00 -> 當天行程
  let target = new Date(now);
  if (hours >= 22) {
    target.setDate(target.getDate() + 1);
  }

  const targetDateStr = `${target.getMonth() + 1}/${target.getDate()}`;
  if (itineraryData && itineraryData.length > 0) {
    const matched = itineraryData.find(d => d.date === targetDateStr);
    if (matched) return matched.date;
  }
  return '9/15';
}

let currentSelectedDate = calculateDefaultFocusDate();
let currentTab = 'timeline';

