// (4) 渲染時間軸卡片列表
function renderTimeline(dateStr, searchKeyword = '') {
  const container = document.getElementById('timelineContainer');
  if (!container || !itineraryData || itineraryData.length === 0) return;

  let daysToRender = [];
  if (searchKeyword.trim()) {
    const kw = searchKeyword.toLowerCase();
    itineraryData.forEach(day => {
      const matchedItems = (day.items || []).filter(item => 
        (item.title && item.title.toLowerCase().includes(kw)) || 
        (item.desc && item.desc.toLowerCase().includes(kw)) ||
        (day.keynote && day.keynote.code && day.keynote.code.toLowerCase().includes(kw))
      );
      if (matchedItems.length > 0 || (day.title && day.title.toLowerCase().includes(kw))) {
        daysToRender.push({ ...day, items: matchedItems.length > 0 ? matchedItems : (day.items || []) });
      }
    });
  } else {
    const day = itineraryData.find(d => d.date === dateStr);
    if (day) daysToRender.push(day);
  }

  if (daysToRender.length === 0) {
    container.innerHTML = `
      <div style="text-align: center; padding: 48px 20px; color: var(--text-tertiary);">
        <p style="font-size: 2.2rem; margin-bottom: 12px;">🔍</p>
        <p style="font-size: 0.95rem;">找不到符合「${searchKeyword}」的行程或憑證</p>
      </div>
    `;
    return;
  }

  container.innerHTML = daysToRender.map(day => `
    <div class="timeline-header-card">
      <div class="th-date-row">
        <span class="th-date-title">${day.date} (${day.weekday}) · ${day.title}</span>
        <span class="th-tag">${day.tag}</span>
      </div>
      <p class="th-summary">${day.summary}</p>
    </div>

    <div class="timeline-list">
      ${(day.items || []).map(item => `
        <div class="timeline-item">
          <div class="tl-bullet">⏱</div>
          <div class="tl-content-card">
            ${item.time ? `<span class="tl-time-badge">${item.time}</span>` : ''}
            <h3 class="tl-title">${item.title}</h3>
            <p class="tl-desc">${item.desc}</p>
            
            ${item.badges && item.badges.length > 0 ? `
              <div class="tl-badges-row">
                ${item.badges.map(b => {
                  let cls = 'status-info';
                  if (b.includes('已預約') || b.includes('已購') || b.includes('✅')) cls = 'status-ok';
                  if (b.includes('未定') || b.includes('現場') || b.includes('⚠️')) cls = 'status-warn';
                  return `<span class="tl-badge ${cls}">${b}</span>`;
                }).join('')}
              </div>
            ` : ''}

            ${item.nav ? `
              <div class="tl-nav-wrapper">
                <a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(item.nav)}" target="_blank" class="btn-tl-nav">
                  <span>🧭 導航至此處</span>
                </a>
              </div>
            ` : ''}
          </div>
        </div>
      `).join('')}
    </div>
  `).join('');
}

