document.addEventListener('DOMContentLoaded', () => {
  const savedTheme = localStorage.getItem('france_theme') || 'dark';
  document.documentElement.setAttribute('data-theme', savedTheme);
  const themeBtn = document.getElementById('btnToggleTheme');
  if (themeBtn) themeBtn.textContent = savedTheme === 'dark' ? '🌙' : '☀️';

  checkAuthStatus();

  document.querySelectorAll('.nav-tab-item').forEach(item => {
    item.addEventListener('click', () => {
      const targetTab = item.getAttribute('data-tab');
      switchTab(targetTab);
    });
  });

  if (themeBtn) {
    themeBtn.addEventListener('click', toggleTheme);
  }

  const logoutBtn = document.getElementById('btnLogout');
  if (logoutBtn) {
    logoutBtn.addEventListener('click', lockApp);
  }

  const searchToggleBtn = document.getElementById('btnToggleSearch');
  const searchDrawer = document.getElementById('searchDrawer');
  const searchInput = document.getElementById('searchInput');

  if (searchToggleBtn && searchDrawer) {
    searchToggleBtn.addEventListener('click', () => {
      searchDrawer.classList.toggle('active');
      if (searchDrawer.classList.contains('active')) {
        searchInput.focus();
      } else {
        searchInput.value = '';
        renderTimeline(currentSelectedDate);
      }
    });
  }

  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      const keyword = e.target.value;
      switchTab('timeline');
      renderTimeline(currentSelectedDate, keyword);
    });
  }

  const pocketFilterBtns = document.querySelectorAll('.filter-chip');
  pocketFilterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      pocketFilterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const cat = btn.getAttribute('data-category');
      renderPocketPlaces(cat);
    });
  });

  // 回到最上面 (Back to Top) 浮動按鈕邏輯
  const btnBackToTop = document.getElementById('btnBackToTop');
  if (btnBackToTop) {
    let isScrollingTicking = false;
    window.addEventListener('scroll', () => {
      if (!isScrollingTicking) {
        window.requestAnimationFrame(() => {
          if (window.scrollY > 260) {
            btnBackToTop.classList.add('show');
          } else {
            btnBackToTop.classList.remove('show');
          }
          isScrollingTicking = false;
        });
        isScrollingTicking = true;
      }
    }, { passive: true });

    btnBackToTop.addEventListener('click', () => {
      window.scrollTo({
        top: 0,
        behavior: 'smooth'
      });
    });
  }

  // 初始化隨行秘書 AI 問答功能
  initAiAssistant();
});

// ==========================================
// 4. 隨行秘書 AI 智能問答模組 (Gemini 2.5 Flash)
// ==========================================
function initAiAssistant() {
  const btnAskAi = document.getElementById('btnAskAi');
  const modal = document.getElementById('aiModalOverlay');
  const btnClose = document.getElementById('btnCloseAi');
  const btnSend = document.getElementById('btnSendAi');
  const input = document.getElementById('aiUserInput');
  const msgContainer = document.getElementById('aiChatMessages');

  if (!btnAskAi || !modal) return;

  // 開啟問答面板
  btnAskAi.addEventListener('click', () => {
    modal.classList.add('active');
    document.body.style.overflow = 'hidden';

    // 若對話為空，加入初次迎賓訊息
    if (msgContainer && msgContainer.children.length === 0) {
      appendAiMessage('assistant', `您好！我是您的 <strong>2026 法國旅行隨行秘書</strong> 🥐。<br><br>我已完整掌握 9/15～10/7 共 23 天的全部行程細節、8 家飯店憑證、11 筆交通票券與 90 處私房好店。<br><br>想查今日行程、問地鐵交通、尋找附近必吃甜點或問精品店動線，隨時問我！`);
    }

    setTimeout(() => {
      if (input) input.focus();
    }, 300);
  });

  // 關閉問答面板
  function closeModal() {
    modal.classList.remove('active');
    document.body.style.overflow = '';
  }

  if (btnClose) btnClose.addEventListener('click', closeModal);
  modal.addEventListener('click', (e) => {
    if (e.target === modal) closeModal();
  });

  // 發送訊息監聽：嚴格依使用者要求，取消 Enter 鍵自動送出（防止注音選字/打字誤觸），僅點擊「送出鈕」才發送
  if (btnSend) {
    btnSend.addEventListener('click', () => handleAiSend());
  }
  if (input) {
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        // 防止換行或預設行為誤送出，依指示保持必須點擊送出鈕
        e.preventDefault();
      }
    });
  }
}

