// 格式化簡易 Markdown
function formatAiResponse(text) {
  if (!text) return '';
  let html = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // 粗體
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
  // 行動連結或重點標記（包含導航超連結）
  html = html.replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2" target="_blank" style="color:var(--accent-ochre);text-decoration:underline;">$1</a>');
  // 清單符號美化
  html = html.replace(/^[ \t]*[\*•-][ \t]+/gm, '• ');
  // 換行
  html = html.replace(/\n/g, '<br>');
  return html;
}

// 插入對話泡泡
function appendAiMessage(role, contentHtml) {
  const msgContainer = document.getElementById('aiChatMessages');
  if (!msgContainer) return null;

  const bubble = document.createElement('div');
  bubble.className = `chat-bubble ${role}`;
  bubble.innerHTML = contentHtml;
  msgContainer.appendChild(bubble);
  msgContainer.scrollTop = msgContainer.scrollHeight;
  return bubble;
}

// 處理發送訊息核心邏輯
async function handleAiSend() {
  const input = document.getElementById('aiUserInput');
  if (!input) return;
  const userText = input.value.trim();
  if (!userText) return;

  input.value = '';
  appendAiMessage('user', formatAiResponse(userText));

  // 1. 本地超速離線判斷（常見問題 0 秒直答，不耗費 API）
  if (userText.includes('停車') && (userText.includes('密碼') || userText.includes('雷恩'))) {
    setTimeout(() => {
      appendAiMessage('assistant', `🅿️ <strong>諾曼第自駕取車與停車密碼：</strong><br><br>• <strong>取車地點</strong>：雷恩火車站北出口 Relay 左側手扶梯至 Sixt 櫃檯<br>• <strong>訂單代碼</strong>：<code>9738701348</code> (Peugeot 3008 休旅)<br>• <strong>停車場電梯密碼</strong>：雷恩 Effia 停車場 0 樓電梯密碼為 <strong style="color:var(--accent-ochre);font-size:1.1rem;">6060</strong><br>• <strong>還車時間</strong>：9/30 18:00 前至 Marne-la-Vallée Chessy 還車。`);
    }, 200);
    return;
  }

  if (userText.includes('緊急') || userText.includes('報警') || userText.includes('求助') || userText.includes('電話')) {
    setTimeout(() => {
      appendAiMessage('assistant', `🚨 <strong>法國官方緊急救助電話：</strong><br><br>• <strong>歐洲通用緊急電話</strong>：<code>112</code> (手機無 SIM 卡或漫遊皆可直撥)<br>• <strong>法國警察局</strong>：<code>17</code><br>• <strong>醫療救護車 (SAMU)</strong>：<code>15</code><br>• <strong>消防局</strong>：<code>18</code><br>• <strong>駐法國台北代表處急難救助專線</strong>：<code>+33-6-80-07-49-94</code>`);
    }, 200);
    return;
  }

  // 2. 檢驗金庫解密狀態
  if (!geminiApiKey) {
    appendAiMessage('assistant', `⚠️ <strong>尚未解鎖行程金庫</strong><br><br>請先在網站上方輸入通關密碼 <strong>8890</strong> 解鎖金庫，隨行秘書便能啟用 AI 智能為您調閱專屬行程與導航！`);
    return;
  }

  // 3. 連線 Google Gemini 2.5 Flash
  const thinkingBubble = appendAiMessage('thinking', `🥐 隨行秘書正在查閱 23 天專屬行程與私房資料庫...`);

  try {
    const systemInstructionText = buildAiSystemInstruction();

    // 歷史上下文組合
    const contents = [];
    aiChatHistory.forEach(h => {
      contents.push({
        role: h.role === 'assistant' ? 'model' : 'user',
        parts: [{ text: h.text }]
      });
    });
    contents.push({
      role: 'user',
      parts: [{ text: userText }]
    });

    const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${geminiApiKey}`;

    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: contents,
        systemInstruction: {
          parts: [{ text: systemInstructionText }]
        },
        generationConfig: {
          temperature: 0.4,
          maxOutputTokens: 8192
        }
      })
    });

    if (thinkingBubble) thinkingBubble.remove();

    if (!res.ok) {
      throw new Error(`API HTTP ${res.status}`);
    }

    const data = await res.json();
    const candidate = data.candidates && data.candidates[0];
    const replyText = candidate?.content?.parts?.[0]?.text || '抱歉，隨行秘書暫時無法讀取此問題的回覆，請稍後再試。';

    appendAiMessage('assistant', formatAiResponse(replyText));

    // 儲存對話紀錄（保留最近 6 輪以控制 token）
    aiChatHistory.push({ role: 'user', text: userText });
    aiChatHistory.push({ role: 'assistant', text: replyText });
    if (aiChatHistory.length > 12) aiChatHistory = aiChatHistory.slice(-12);

  } catch (err) {
    console.warn('Gemini API Error:', err);
    if (thinkingBubble) thinkingBubble.remove();
    appendAiMessage('assistant', `⚠️ <strong>連線暫時不順暢</strong><br><br>目前網路訊號較微弱或 API 請求受限。建議您可以：<br>1. 點選上方的<strong>快捷問題標籤</strong>直接調閱離線憑證。<br>2. 切換至【每日行程】或【交通指南】查看離線手冊。`);
  }
}

